let DATA=[],CATALOG=[];let part=0,limit=15,selected=[];const $=s=>document.querySelector(s),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const colors=['#3e4d3b','#3b284a','#8b492d','#263d50','#68614b','#3b5255'];let shown=[];function render(){let q=$('#search').value.toLocaleLowerCase();let arr=DATA.filter(d=>(!part||d.part===part)&&d.title.toLocaleLowerCase().includes(q));arr.sort((a,b)=>a.title.localeCompare(b.title,'en',{sensitivity:'base',numeric:true}));$('#count').textContent=arr.length+' bài đọc'+(part?' · Passage '+part:'');shown=arr.slice(0,limit);let cols=innerWidth<=560?2:innerWidth<=900?3:5;$('#books').innerHTML='';for(let i=0;i<shown.length;i+=cols){let shelf=document.createElement('div');shelf.className='shelf';shelf.innerHTML=shown.slice(i,i+cols).map((d,j)=>`<button class="book" style="--color:${colors[(i+j)%colors.length]}" data-id="${esc(d.id)}" aria-label="Xem ${esc(d.title)}"><span class="spine"><span>${esc(d.title)}</span></span><span class="book-top"></span><span class="book-bottom"></span><span class="book-edge"></span><span class="front">${d.image?`<img src="${d.image}" alt="" loading="lazy">`:''}<span class="shade"></span><span class="booktext"><span class="part">Passage ${d.part}</span><h2>${esc(d.title)}</h2><span class="types">${d.types.map(esc).join('<br>')}</span></span></span></button>`).join('');$('#books').append(shelf)}if(!arr.length)$('#books').innerHTML='<div class="empty">Không tìm thấy bài đọc. Hãy thử tên khác.</div>';$('#more').hidden=arr.length<=limit;document.querySelectorAll('.book').forEach(b=>b.onclick=()=>openLesson(b.dataset.id))}function openLesson(id){let d=DATA.find(x=>x.id===id);$('#detail').innerHTML=`<div class="detail">${d.image?`<img src="${d.image}" alt="${esc(d.cover?.alt||'')}">`:''}<div><span class="part">Passage ${d.part} · ${d.count} câu</span><h2>${esc(d.title)}</h2><p>${d.types.map(esc).join('<br>')}</p><div class="actions"><a class="button primary" href="${esc(d.url)}" target="_blank" rel="noopener">Vào làm bài ↗</a></div></div></div><p class="notice"></p>`;$('#lesson').showModal()}document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>{part=+b.dataset.part;limit=15;document.querySelectorAll('[data-part]').forEach(x=>x.classList.toggle('active',x===b));render()});$('#search').oninput=()=>{limit=15;render()};$('#more').onclick=()=>{limit+=15;render()};document.querySelectorAll('dialog .close').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){let r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));function random(){try{selected=FullTestCore.select(CATALOG,localStorage);$('#start-test').disabled=false;$('#testbody').innerHTML=selected.map(d=>`<div class="selected"><b>Passage ${d.part}</b><br>${esc(d.title)}</div>`).join('')+'<div class="actions"><button id="again">Chọn ngẫu nhiên lại</button></div>';$('#again').onclick=random;$('#random').classList.add('primary');$('#manual').classList.remove('primary');$('#test-status').textContent='Ưu tiên bài chưa làm. Bộ đề gồm 40 câu.'}catch{$('#test-status').textContent='Chưa tải được đủ bài. Vui lòng thử lại.'}}
function manual(){
 $('#manual').classList.add('primary');$('#random').classList.remove('primary');
 const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase().trim();
 selected=[1,2,3].map(p=>selected.find(d=>d?.part===p)||null);
 $('#testbody').innerHTML='<div class="pick">'+[1,2,3].map(p=>`<label for="find-p${p}">Passage ${p}</label><input id="find-p${p}" type="search" placeholder="Tìm tên bài Passage ${p}..." aria-label="Tìm tên bài Passage ${p}" style="width:100%;margin:0 0 8px"><select id="p${p}" size="5" aria-label="Chọn bài Passage ${p}"></select><p id="chosen-p${p}" class="notice" style="margin:6px 0 18px"></p>`).join('')+'</div>';
 function update(){selected.forEach((d,i)=>$('#chosen-p'+(i+1)).textContent=d?'Đã chọn: '+d.title:'Chưa chọn bài');$('#start-test').disabled=!selected.every(Boolean);$('#test-status').textContent='Đã chọn '+selected.filter(Boolean).length+'/3 passages.'}
 [1,2,3].forEach(p=>{const input=$('#find-p'+p),list=$('#p'+p);function draw(){const items=CATALOG.filter(d=>d.part===p&&d.count===(p===3?14:13)&&normalize(d.title).includes(normalize(input.value))).sort((a,b)=>a.title.localeCompare(b.title));list.replaceChildren();for(const d of items){const option=document.createElement('option');option.value=d.id;option.textContent=d.title;option.selected=selected[p-1]?.id===d.id;list.append(option)}if(!items.length){const option=document.createElement('option');option.textContent='Không tìm thấy bài phù hợp';option.disabled=true;list.append(option)}if(!items.some(d=>d.id===selected[p-1]?.id))list.selectedIndex=-1}input.oninput=draw;list.onchange=()=>{selected[p-1]=CATALOG.find(d=>d.id===list.value)||null;update()};draw()});update();$('#find-p1').focus();
}
$('#start-test').onclick=()=>{try{const ids=selected.map(d=>d.id);FullTestCore.manual(CATALOG,ids);location.href='full-test.html?'+new URLSearchParams({mode:'manual',p1:ids[0],p2:ids[1],p3:ids[2]})}catch{$('#test-status').textContent='Hãy chọn đủ 3 passages hợp lệ.'}};
$('#random').onclick=random;$('#manual').onclick=manual;$('#full').onclick=()=>{random();$('#test').showModal()};let prevCols=0;window.addEventListener('resize',()=>{let c=innerWidth<=560?2:innerWidth<=900?3:5;if(c!==prevCols){prevCols=c;render()}});render();
async function boot(){try{const [response,overrides]=await Promise.all([fetch('lesson-catalog.json',{cache:'no-cache'}),fetch('cover-overrides.json',{cache:'no-cache'}).then(r=>r.ok?r.json():{}).catch(()=>({}))]);if(!response.ok)throw Error();CATALOG=await response.json();DATA=CATALOG.map(d=>({...d,cover:overrides[d.id]||d.cover,image:(overrides[d.id]||d.cover)?.asset,url:'exam.html?lesson='+encodeURIComponent(d.id)}));for(const [i,card]of [...document.querySelectorAll('#legacy-source article')].entries()){const link=card.querySelector('.open-lesson'),url=link.getAttribute('href'),cover=overrides[url];DATA.push({id:'legacy-'+i,title:card.querySelector('h3').textContent,part:+card.dataset.part,count:+card.dataset.part===3?14:13,types:card.querySelector('.meta').textContent.split(' — '),image:cover?.asset||card.querySelector('img').getAttribute('src'),cover:cover||{alt:card.querySelector('img').alt},url})}$('#load-status').textContent='';$('#start-test').disabled=false;render();try{const draft=JSON.parse(localStorage.getItem('ielts-full-test-draft')||'null');if(draft&&!draft.submitted){const resume=document.createElement('a');resume.className='button';resume.href='full-test.html?resume=1';resume.textContent='Tiếp tục bộ đề';document.querySelector('header').append(resume)}}catch{}}catch{$('#load-status').textContent='Không tải được kho bài. Vui lòng tải lại trang.'}}
$('#start-test').disabled=true;boot();
